"use strict";

/**
 * Stage 1.6W.1 — brings the hand-maintained pages under the canonical shell.
 *
 * Scope: the 95 hand-localized legal and support pages, the 20 account-deletion
 * redirects and the download page. The 20 landing pages are generated by
 * scripts/generate-landing-pages.js and the 25 legal and Translation
 * Information routes by scripts/generate-legal-pages.js; neither is touched
 * here.
 *
 * The hard rule for this script: it adds structure and never writes prose. The
 * localized legal text that goes in comes out unchanged, character for
 * character. Where a heading had lost its markup — several locales' pages carry
 * their page title as a bare text node with no element at all, which no screen
 * reader will ever announce as a heading — the existing words are wrapped, not
 * rewritten or translated.
 *
 * Running it twice produces the same tree as running it once.
 *
 * Run with: node scripts/apply-page-shell.js
 */

const fs = require("fs");
const path = require("path");

const { LOCALES, CHROME, applyShell, isRtl } = require("./page-shell");

const ROOT = path.resolve(__dirname, "..");

/** Element names that do not close, so they never change nesting depth. */
const VOID_ELEMENTS = new Set([
  "area", "base", "br", "col", "embed", "hr", "img", "input",
  "link", "meta", "param", "source", "track", "wbr"
]);

/**
 * Text that sits directly inside `<body>` with no element around it.
 *
 * A bare text node is invisible to every structural tool a person might use:
 * it is not a heading, not a paragraph, and not reachable by "next heading".
 * The first such run on a page with no `<h1>` is the page title that lost its
 * tag; the rest are paragraphs that lost theirs.
 */
function wrapOrphanText(bodyHtml) {
  const tags = [...bodyHtml.matchAll(/<\/?([a-zA-Z][a-zA-Z0-9-]*)\b[^>]*>/g)];
  const runs = [];
  let depth = 0;
  let cursor = 0;

  for (const tag of tags) {
    if (depth === 0 && tag.index > cursor) {
      runs.push({ start: cursor, end: tag.index });
    }
    const name = tag[1].toLowerCase();
    const isClosing = tag[0].startsWith("</");
    const selfClosing = tag[0].endsWith("/>") || VOID_ELEMENTS.has(name);
    if (!selfClosing) depth += isClosing ? -1 : 1;
    if (depth < 0) depth = 0;
    cursor = tag.index + tag[0].length;
  }
  if (depth === 0 && cursor < bodyHtml.length) {
    runs.push({ start: cursor, end: bodyHtml.length });
  }

  const meaningful = runs.filter(({ start, end }) => bodyHtml.slice(start, end).trim());
  if (meaningful.length === 0) return bodyHtml;

  const hasHeading = /<h1\b/i.test(bodyHtml);
  let output = "";
  let previous = 0;
  let first = true;

  for (const run of meaningful) {
    // A blank line separated two paragraphs before their tags were lost, so it
    // still separates them now. Merging them into one element would fuse a
    // page title onto the sentences beneath it.
    const blocks = bodyHtml
      .slice(run.start, run.end)
      .split(/\n\s*\n/)
      .map((block) => block.trim())
      .filter(Boolean);

    output += bodyHtml.slice(previous, run.start);
    for (const block of blocks) {
      const element = first && !hasHeading ? "h1" : "p";
      first = false;
      output += `\n<${element}>${block}</${element}>\n`;
    }
    previous = run.end;
  }
  return output + bodyHtml.slice(previous);
}

/**
 * The support pages announce the contact address as an `<h2>`.
 *
 * An email address is not a section heading, and a screen-reader user tabbing
 * the heading list hears "heading level two, ulmoxapp at outlook dot com" with
 * no idea what section it opens. The address keeps its prominence and becomes
 * something a reader can actually act on.
 */
function contactHeadingToLink(html) {
  return html.replace(
    /<h2>\s*([^<@\s]+@[^<\s]+)\s*<\/h2>/gi,
    (whole, address) =>
      `<p class="contact-email"><a href="mailto:${address}">${address}</a></p>`
  );
}

function transformBody(html, transform) {
  return html.replace(
    /(<body\b[^>]*>)([\s\S]*?)(<\/body>)/i,
    (whole, open, body, close) => `${open}${transform(body)}${close}`
  );
}

/* -------------------------------------------------------------------------- */
/* The hand-maintained localized legal and support pages                      */
/* -------------------------------------------------------------------------- */

const LOCALIZED_PAGES = Object.freeze([
  "privacy.html", "terms.html", "safety.html", "support.html", "delete_account.html"
]);

function retrofitLocalizedPage(route, html) {
  let output = transformBody(html, (body) => wrapOrphanText(body));
  output = contactHeadingToLink(output);

  // A `<div class="footer">` is a footer in everything but its element name.
  // Promoting it keeps its localized copyright line and gives the page the
  // landmark it was missing.
  output = output
    .replace(/<div class="footer">/i, '<footer class="footer">')
    .replace(/(<footer class="footer">[\s\S]*?)<\/div>/i, "$1</footer>");

  return applyShell(output, { route });
}

/* -------------------------------------------------------------------------- */
/* The account-deletion redirects                                             */
/* -------------------------------------------------------------------------- */

/**
 * `/<locale>/delete-account/` and `/delete-account/`.
 *
 * These stubs shipped their entire visible text in English on all 19 localized
 * routes — "This page has moved. Delete your ULMOX account." under `lang="ar"`,
 * `lang="ja"` and the rest. They are regenerated here from the localized
 * wording in scripts/page-shell.js.
 *
 * They stay `noindex`, keep their canonical link and keep the meta refresh, so
 * the hyphenated route still forwards to the canonical page. They carry no
 * analytics: scripts/build-site.js excludes every deletion route by path.
 */
function deletionRedirect(locale, { root = false } = {}) {
  const chrome = CHROME[locale];
  const target = root ? "/delete_account.html" : `/${locale}/delete_account.html`;
  const dir = isRtl(locale) ? ' dir="rtl"' : "";
  const route = root ? "delete-account/index.html" : `${locale}/delete-account/index.html`;

  return applyShell(
    `<!DOCTYPE html>
<html lang="${locale}"${dir}>
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${chrome.deleteHeading} - ULMOX</title>
  <meta name="description" content="${chrome.moved} ${chrome.deleteHeading}" />
  <meta name="robots" content="noindex" />
  <link rel="canonical" href="${target}" />
  <meta http-equiv="refresh" content="0; url=${target}" />
  <style>
    body {
      margin: 0;
      padding: 40px 20px;
      background: #0d0d0f;
      color: #ffffff;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
      line-height: 1.7;
    }

    main { max-width: 640px; margin: 0 auto; }
    h1 { font-size: clamp(24px, 5vw, 32px); margin: 0 0 12px; }
    p { color: #d6d6d6; font-size: 17px; }
    a { color: #ffd24d; }
  </style>
</head>
<body>
  <h1>${chrome.deleteHeading}</h1>
  <p>${chrome.moved}</p>
  <p><a href="${target}">${chrome.deleteAccount}</a></p>
</body>
</html>
`,
    { route }
  );
}

/* -------------------------------------------------------------------------- */

function generate(targetRoot = ROOT) {
  const written = [];

  for (const locale of LOCALES) {
    for (const page of LOCALIZED_PAGES) {
      const route = `${locale}/${page}`;
      const file = path.join(targetRoot, route);
      const html = fs.readFileSync(file, "utf8");
      fs.writeFileSync(file, retrofitLocalizedPage(route, html), "utf8");
      written.push(route);
    }

    const redirect = `${locale}/delete-account/index.html`;
    const redirectFile = path.join(targetRoot, redirect);
    fs.mkdirSync(path.dirname(redirectFile), { recursive: true });
    fs.writeFileSync(redirectFile, deletionRedirect(locale), "utf8");
    written.push(redirect);
  }

  const rootRedirect = path.join(targetRoot, "delete-account", "index.html");
  fs.mkdirSync(path.dirname(rootRedirect), { recursive: true });
  fs.writeFileSync(rootRedirect, deletionRedirect("en", { root: true }), "utf8");
  written.push("delete-account/index.html");

  // The download page already has a <main> and a description; it needs the id
  // the skip link targets, the skip link itself and the footer landmark.
  const downloadRoute = "download/index.html";
  const downloadFile = path.join(targetRoot, downloadRoute);
  fs.writeFileSync(
    downloadFile,
    applyShell(fs.readFileSync(downloadFile, "utf8"), { route: downloadRoute }),
    "utf8"
  );
  written.push(downloadRoute);

  return written;
}

if (require.main === module) {
  const written = generate();
  console.log(`Shelled ${written.length} pages.`);
}

module.exports = {
  LOCALIZED_PAGES,
  wrapOrphanText,
  contactHeadingToLink,
  retrofitLocalizedPage,
  deletionRedirect,
  generate,
};
